import SwiftUI

/// Single-colour language logos from Simple Icons 16.32.0 (CC0, simpleicons.org;
/// the marks stay their owners' trademarks). Paths are the upstream 24×24 `d`
/// strings normalised offline to absolute M/L/C/Z (arcs → cubics, svgpath).
enum SimpleIcons {
  static let paths: [String: Path] = raw.mapValues(parse)

  /// Parses the normalised M/L/C/Z subset only.
  static func parse(_ d: String) -> Path {
    var p = Path()
    var cmd: Character = "M"
    var nums: [CGFloat] = []
    func flush() {
      switch cmd {
      case "M" where nums.count == 2: p.move(to: CGPoint(x: nums[0], y: nums[1]))
      case "L" where nums.count == 2: p.addLine(to: CGPoint(x: nums[0], y: nums[1]))
      case "C" where nums.count == 6:
        p.addCurve(to: CGPoint(x: nums[4], y: nums[5]), control1: CGPoint(x: nums[0], y: nums[1]),
                   control2: CGPoint(x: nums[2], y: nums[3]))
      default: return
      }
      nums.removeAll()
    }
    var token = ""
    for ch in d + " " {
      if ch.isNumber || ch == "." || (ch == "-" && token.isEmpty) { token.append(ch); continue }
      if let n = Double(token) { nums.append(n); flush() }
      token = ch == "-" ? "-" : ""
      if ch == "Z" { p.closeSubpath() } else if ch.isLetter { cmd = ch }
    }
    return p
  }

